B.a2d=s(["Oh, that is lovely. Thank you for sharing it with me.","\u0648\u0627\u06cc\u060c \u062e\u06cc\u0644\u06cc \u0642\u0634\u0646\u06af\u0647. \u0645\u0645\u0646\u0648\u0646 \u06a9\u0647 \u0628\u0627 \u0645\u0646 \u062f\u0631\u0645\u06cc\u0648\u0646\u0634 \u06af\u0630\u0627\u0634\u062a\u06cc."],t.s)
B.a41=s(["Beautifully written \u2014 I might pin it on the fridge!","\u062e\u06cc\u0644\u06cc \u0632\u06cc\u0628\u0627 \u0646\u0648\u0634\u062a\u06cc \u2014 \u0634\u0627\u06cc\u062f \u0628\u0686\u0633\u0628\u0648\u0646\u0645\u0634 \u0631\u0648 \u06cc\u062e\u0686\u0627\u0644!"],t.s)
B.a2J=s([B.a2d,B.a41],t.rj)
